602	\N	reporting.dashboard_widgets	3	CREATE	\N	2026-06-22 18:26:40.817927+00	\N	{"id": 3, "is_active": true, "widget_code": "RECENT_ACTIVITY", "widget_name": "آخر النشاطات", "widget_type": "LIST", "configuration": {"query": "SELECT created_at, description FROM system.audit_log ORDER BY created_at DESC LIMIT 10", "title": "آخر النشاطات", "refresh_interval": 120}}
603	\N	reporting.dashboard_widgets	4	CREATE	\N	2026-06-22 18:26:40.817927+00	\N	{"id": 4, "is_active": true, "widget_code": "AVG_REVIEW_TIME", "widget_name": "متوسط وقت المراجعة", "widget_type": "GAUGE", "configuration": {"query": "SELECT AVG(EXTRACT(DAY FROM (completed_at - started_at))) FROM committee.scientific_reviews WHERE completed_at IS NOT NULL", "title": "متوسط وقت المراجعة (أيام)", "refresh_interval": 3600}}
604	\N	reporting.dashboard_widgets	5	CREATE	\N	2026-06-22 18:26:40.817927+00	\N	{"id": 5, "is_active": true, "widget_code": "APPS_OVER_TIME", "widget_name": "الطلبات عبر الوقت", "widget_type": "LINE_CHART", "configuration": {"query": "SELECT DATE_TRUNC('month', submission_date) AS month, COUNT(*) FROM core.applications WHERE submission_date IS NOT NULL GROUP BY month ORDER BY month", "title": "الطلبات المقدمة عبر الوقت", "refresh_interval": 3600}}
605	\N	reporting.dashboard_widgets	6	CREATE	\N	2026-06-22 18:26:40.817927+00	\N	{"id": 6, "is_active": true, "widget_code": "COMMITTEE_MEETINGS", "widget_name": "اجتماعات اللجنة القادمة", "widget_type": "CALENDAR", "configuration": {"query": "SELECT meeting_date, location, meeting_status FROM committee.committee_meetings WHERE meeting_date >= NOW() ORDER BY meeting_date", "title": "اجتماعات اللجنة القادمة", "refresh_interval": 600}}
606	\N	reporting.report_definitions	1	CREATE	\N	2026-06-22 18:26:40.817927+00	\N	{"id": 1, "is_active": true, "report_code": "RPT_APPS_BY_STATUS", "report_name": "تقرير الطلبات حسب الحالة", "sql_definition": "SELECT a.application_number, a.application_type, a.current_status, a.submission_date, u.first_name_ar || ' ' || u.last_name_ar AS researcher, p.title_ar AS project_title FROM core.applications a JOIN security.users u ON a.submitted_by = u.id JOIN core.projects p ON a.project_id = p.id ORDER BY a.submission_date DESC", "report_category": "APPLICATIONS"}
607	\N	reporting.report_definitions	2	CREATE	\N	2026-06-22 18:26:40.817927+00	\N	{"id": 2, "is_active": true, "report_code": "RPT_REVIEW_PERFORMANCE", "report_name": "تقرير أداء المراجعين", "sql_definition": "SELECT u.first_name_ar || ' ' || u.last_name_ar AS reviewer, COUNT(sr.id) AS reviews_completed, AVG(EXTRACT(DAY FROM (sr.completed_at - sr.started_at))) AS avg_days FROM committee.scientific_reviews sr JOIN security.users u ON sr.reviewer_id = u.id WHERE sr.completed_at IS NOT NULL GROUP BY sr.reviewer_id, u.first_name_ar, u.last_name_ar ORDER BY avg_days", "report_category": "REVIEWS"}
608	\N	reporting.report_definitions	3	CREATE	\N	2026-06-22 18:26:40.817927+00	\N	{"id": 3, "is_active": true, "report_code": "RPT_SAFEY_SUMMARY", "report_name": "ملخص السلامة", "sql_definition": "SELECT a.application_number, COUNT(ae.id) AS total_events, COUNT(sae.id) AS serious_events FROM core.applications a LEFT JOIN safety.adverse_events ae ON a.id = ae.application_id LEFT JOIN safety.serious_adverse_events sae ON ae.id = sae.adverse_event_id GROUP BY a.id, a.application_number ORDER BY total_events DESC", "report_category": "SAFETY"}
609	\N	reporting.report_definitions	4	CREATE	\N	2026-06-22 18:26:40.817927+00	\N	{"id": 4, "is_active": true, "report_code": "RPT_MONITORING_STATUS", "report_name": "حالة المراقبة", "sql_definition": "SELECT mp.plan_code, a.application_number, mp.monitoring_type, mp.status_code, COUNT(mv.id) AS visits_completed FROM monitoring.monitoring_plans mp JOIN core.applications a ON mp.application_id = a.id LEFT JOIN monitoring.monitoring_visits mv ON mp.id = mv.monitoring_plan_id AND mv.visit_status = 'COMPLETED' GROUP BY mp.id, mp.plan_code, a.application_number, mp.monitoring_type, mp.status_code", "report_category": "MONITORING"}
610	\N	reporting.report_definitions	5	CREATE	\N	2026-06-22 18:26:40.817927+00	\N	{"id": 5, "is_active": true, "report_code": "RPT_COMMITTEE_DECISIONS", "report_name": "قرارات اللجنة", "sql_definition": "SELECT cm.meeting_number, cm.meeting_date, COUNT(v.id) AS total_votes, v2.vote_value, COUNT(v2.id) AS vote_count FROM committee.committee_meetings cm JOIN committee.voting_sessions vs ON cm.id = vs.meeting_id JOIN committee.votes v ON vs.id = v.voting_session_id JOIN committee.votes v2 ON vs.id = v2.voting_session_id GROUP BY cm.meeting_number, cm.meeting_date, v2.vote_value ORDER BY cm.meeting_date", "report_category": "COMMITTEE"}
