COPY reporting.dashboard_widgets (id, widget_code, widget_name, widget_type, configuration, is_active) FROM stdin;
1	PENDING_APPS	الطلبات قيد الانتظار	COUNTER	{"query": "SELECT COUNT(*) FROM core.applications WHERE current_status NOT IN ('APPROVED','REJECTED','WITHDRAWN')", "title": "الطلبات قيد الانتظار", "refresh_interval": 300}	t
2	APPS_BY_STATUS	الطلبات حسب الحالة	PIE_CHART	{"query": "SELECT current_status, COUNT(*) FROM core.applications GROUP BY current_status", "title": "توزيع الطلبات حسب الحالة", "refresh_interval": 600}	t
3	RECENT_ACTIVITY	آخر النشاطات	LIST	{"query": "SELECT created_at, description FROM system.audit_log ORDER BY created_at DESC LIMIT 10", "title": "آخر النشاطات", "refresh_interval": 120}	t
4	AVG_REVIEW_TIME	متوسط وقت المراجعة	GAUGE	{"query": "SELECT AVG(EXTRACT(DAY FROM (completed_at - started_at))) FROM committee.scientific_reviews WHERE completed_at IS NOT NULL", "title": "متوسط وقت المراجعة (أيام)", "refresh_interval": 3600}	t
5	APPS_OVER_TIME	الطلبات عبر الوقت	LINE_CHART	{"query": "SELECT DATE_TRUNC('month', submission_date) AS month, COUNT(*) FROM core.applications WHERE submission_date IS NOT NULL GROUP BY month ORDER BY month", "title": "الطلبات المقدمة عبر الوقت", "refresh_interval": 3600}	t
6	COMMITTEE_MEETINGS	اجتماعات اللجنة القادمة	CALENDAR	{"query": "SELECT meeting_date, location, meeting_status FROM committee.committee_meetings WHERE meeting_date >= NOW() ORDER BY meeting_date", "title": "اجتماعات اللجنة القادمة", "refresh_interval": 600}	t
