COPY reporting.report_definitions (id, report_code, report_name, report_category, sql_definition, is_active) FROM stdin;
1	RPT_APPS_BY_STATUS	تقرير الطلبات حسب الحالة	APPLICATIONS	SELECT a.application_number, a.application_type, a.current_status, a.submission_date, u.first_name_ar || ' ' || u.last_name_ar AS researcher, p.title_ar AS project_title FROM core.applications a JOIN security.users u ON a.submitted_by = u.id JOIN core.projects p ON a.project_id = p.id ORDER BY a.submission_date DESC	t
2	RPT_REVIEW_PERFORMANCE	تقرير أداء المراجعين	REVIEWS	SELECT u.first_name_ar || ' ' || u.last_name_ar AS reviewer, COUNT(sr.id) AS reviews_completed, AVG(EXTRACT(DAY FROM (sr.completed_at - sr.started_at))) AS avg_days FROM committee.scientific_reviews sr JOIN security.users u ON sr.reviewer_id = u.id WHERE sr.completed_at IS NOT NULL GROUP BY sr.reviewer_id, u.first_name_ar, u.last_name_ar ORDER BY avg_days	t
3	RPT_SAFEY_SUMMARY	ملخص السلامة	SAFETY	SELECT a.application_number, COUNT(ae.id) AS total_events, COUNT(sae.id) AS serious_events FROM core.applications a LEFT JOIN safety.adverse_events ae ON a.id = ae.application_id LEFT JOIN safety.serious_adverse_events sae ON ae.id = sae.adverse_event_id GROUP BY a.id, a.application_number ORDER BY total_events DESC	t
4	RPT_MONITORING_STATUS	حالة المراقبة	MONITORING	SELECT mp.plan_code, a.application_number, mp.monitoring_type, mp.status_code, COUNT(mv.id) AS visits_completed FROM monitoring.monitoring_plans mp JOIN core.applications a ON mp.application_id = a.id LEFT JOIN monitoring.monitoring_visits mv ON mp.id = mv.monitoring_plan_id AND mv.visit_status = 'COMPLETED' GROUP BY mp.id, mp.plan_code, a.application_number, mp.monitoring_type, mp.status_code	t
5	RPT_COMMITTEE_DECISIONS	قرارات اللجنة	COMMITTEE	SELECT cm.meeting_number, cm.meeting_date, COUNT(v.id) AS total_votes, v2.vote_value, COUNT(v2.id) AS vote_count FROM committee.committee_meetings cm JOIN committee.voting_sessions vs ON cm.id = vs.meeting_id JOIN committee.votes v ON vs.id = v.voting_session_id JOIN committee.votes v2 ON vs.id = v2.voting_session_id GROUP BY cm.meeting_number, cm.meeting_date, v2.vote_value ORDER BY cm.meeting_date	t
\.
